from zipfile import ZipFile
from lxml import etree
with ZipFile('/app/New_Club_Spring_2018_Training.pptx') as z:
 for n in z.namelist():
  if n.startswith('ppt/slides/slide') and n.endswith('.xml'):
   root=etree.fromstring(z.read(n))
